def solve(data):
    words = iter(data['words'])
    reading = data['start']
    readings = []
    for control in words:
        if control < 0:
            delta = next(words)
            for _ in range(-control):
                reading += delta
                readings.append(reading)
        else:
            for _ in range(control):
                reading += next(words)
                readings.append(reading)
