def solve(data):
    def numeric_key(digits):
        return len(digits), digits

    def precedence(version):
        core, separator, suffix = version.partition('-')
        parts = tuple(numeric_key(part) for part in core.split('.'))
        identifiers = []
        if separator:
            for item in suffix.split('.'):
                if item.isdigit():
                    identifiers.append((0, numeric_key(item)))
                else:
                    identifiers.append((1, item))
        return parts, not separator, identifiers

    return sorted(data['versions'], key=precedence)
